package gg.neonnexus.smpplatform.integrations.skript;
import ch.njol.skript.lang.Effect; import ch.njol.skript.lang.Expression; import ch.njol.skript.lang.SkriptParser.ParseResult; import ch.njol.util.Kleenean; import org.bukkit.entity.Player; import org.bukkit.event.Event;
public final class EffNexusPlatformEvent extends Effect { private Expression<String> type,metadata; private Expression<Player> players; @SuppressWarnings("unchecked") @Override public boolean init(Expression<?>[] x,int m,Kleenean d,ParseResult p){type=(Expression<String>)x[0];if(m==1){metadata=(Expression<String>)x[1];players=(Expression<Player>)x[2];}else players=(Expression<Player>)x[1];return true;} @Override protected void execute(Event e){String t=type.getSingle(e);String md=metadata==null?"":metadata.getSingle(e);if(t!=null)for(Player p:players.getArray(e))NexusSkriptRegistry.bridge().triggerPlatformEvent(p.getUniqueId(),t,md==null?"":md);} @Override public String toString(Event e,boolean d){return "nexus platform event";} }
